#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G016 stage 0 driver, on the control box (no build or benchmark here: it restores and starts runs on box3900x, then waits).
# For each "<name>:<MemoryMax>[:<binary>]": restore box3900x's working DB to stressnet_h3106400 (snapctl.sh restore,
# sha256-verified), start g016s0_run.sh detached on box3900x, wait for its marker. Stops at the first abort.
# S0SNAP: the snapshot to restore (default stressnet_h3106400, popped; stressnet_h3106400c is its compacted copy).
# S0WRAP: a command the runner puts before the test node's binary (G016 s0w: taskset -c 0-3).
# usage: [S0WRAP=<cmd>] [S0TOP=<height>] [RESID=1] [S0EXTRA=<monerod args>] [S0SNAP=<snapshot>] [S0PERF=1] g016s0_drive.sh <name:level[:binary]>...
set -u
R=$HOME/work/research-artifacts/g016s0
for spec in "$@"; do
  name=${spec%%:*}; rest=${spec#*:}; level=${rest%%:*}; bin=""; [ "$rest" != "$level" ] && bin=${rest#*:}
  echo "== $name level $level binary ${bin:-the .6 release} snapshot ${S0SNAP:-stressnet_h3106400} $(date -u +%FT%TZ)"
  ssh -n box3900x "pgrep -u $USER -x monerod" > /dev/null && { echo "a monerod runs on box3900x; stop"; exit 1; }
  ~/snapshots/snapctl.sh restore box3900x ${S0SNAP:-stressnet_h3106400} || { echo "restore failed; stop"; exit 1; }
  ssh -n box3900x "cd ~/work/g016 && (BIN_OVERRIDE='$bin' TOP=${S0TOP:-3123269} RESID=${RESID:-} EXTRA_ARGS='${S0EXTRA:-}' PERF='${S0PERF:-}' PERF_AT='${S0PERFAT:-1200}' PERF_S='${S0PERFS:-30}' PERF_STACK='${S0PERFSTACK:-8192}' NODE_WRAP='${S0WRAP:-}' setsid nohup ./g016s0_run.sh $name $level > $name.out 2>&1 < /dev/null &)"
  until ssh -n box3900x "grep -q G016S0_RUN_DONE $R/$name/run.log 2>/dev/null"; do sleep 60; done
  ssh -n box3900x "tail -6 $R/$name/run.log"
  ssh -n box3900x "grep -q 'G016S0_RUN_DONE abort' $R/$name/run.log" && { echo "run aborted; stop"; exit 1; }
done
echo "G016S0_DRIVE_DONE $(date -u +%FT%TZ)"
